func keyIsSecret(key string) bool {
    if key == "" {
        return false
    }
    lower := strings.ToLower(key)
    for _, f := range secretKeyFragments {
        if strings.Contains(lower, f) {
            return true
        }
    }
    return false
}

func findVersion(versions []releases.OKDVersion, query string) (releases.OKDVersion, bool) {
    query = strings.TrimSpace(query)
    for _, v := range versions {
        if v.Version == query || v.Tag == query {
            return v, true
        }
    }
    return releases.OKDVersion{}, false
}

func (n *statusNode) isReady() bool {
    for _, c := range n.Status.Conditions {
        if c.Type == phase.ConditionTypeReady && c.Status == phase.ConditionStatusTrue {
            return true
        }
    }
    return false
}

slices.SortFunc(series.Versions, func(a, b OKDVersion) int {
    if cmp := semver.Compare("v"+a.Version, "v"+b.Version); cmp != 0 {
        return -cmp // descending
    }
    if !a.ReleaseDate.Equal(b.ReleaseDate) {
        return b.ReleaseDate.Compare(a.ReleaseDate)
    }
    return strings.Compare(b.Version, a.Version)
})

